'use strict';
const $=id=>document.getElementById(id);
const SAMPLE='https://cdn.prod.website-files.com/635c470cc81318fc3e9c1e0e/6a45531a1aa3aa3a11e2cb72_DECA_FTDM_2026_District_Event_Sample.pdf';
const GUIDE='https://cdn.prod.website-files.com/635c470cc81318fc3e9c1e0e/6a8327f7f7f637d914a9fc71_HS_TDM_Guidelines.pdf';
