let currentCase='family',caseDrafts=new Map(),testAnswers=null;
function saveDraft(){caseDrafts.set(currentCase,{transcript:$('transcript').value,photos:[...photos],revealed,feedback,answers:revealed?questions.map((q,i)=>$('answer'+i)?.value||''):[],testAnswers,sessionStarted,deadline,prepDeadline});}
function selectCase(id){if(recording||busy){message('Stop recording and wait for transcription before switching cases.');$('caseselect').value=currentCase;return;}const c=CASE_LIBRARY.find(x=>x.id===id);if(!c)return;saveDraft();currentCase=id;scenario=c.scenario;indicators=[...c.indicators];questions=[...c.questions];const d=caseDrafts.get(id)||{};photos=d.photos||[];revealed=!!d.revealed;feedback=d.feedback||null;testAnswers=d.testAnswers||null;sessionStarted=!!d.sessionStarted;deadline=d.deadline||null;prepDeadline=d.prepDeadline||null;$('transcript').value=d.transcript||'';$('pis').value=indicators.join('\n');$('qs').value='';$('custom').value='';$('questions').replaceChildren();if(revealed){renderQuestions();(d.answers||[]).forEach((a,i)=>$('answer'+i).value=a);}gallery();if(feedback)renderResults();else{$('results').replaceChildren(textNode('div','Complete this case to get its scorecard.','card'));$('download').disabled=true;}lastRecording=null;$('retrytranscribe').hidden=true;$('playback').hidden=true;$('playback').removeAttribute('src');$('recstatus').textContent='Ready';$('clock').textContent=deadline?format(Math.ceil((deadline-Date.now())/1000)):'15:00';$('prepclock').textContent=prepDeadline?format(Math.ceil((prepDeadline-Date.now())/1000)):'30:00';$('caseselect').value=id;$('casetitle').textContent=c.title;$('casebrief').textContent=c.scenario;$('casetag').textContent=c.tag;$('casenote').textContent=c.note;$('samplelink').href=c.source;$('samplelink').textContent=c.tag.startsWith('Original')?'FTDM event reference ↗':'Read source case ↗';$('casepis').replaceChildren(...indicators.map(x=>textNode('li',x)));message('');show(0);controls();}
for(const c of CASE_LIBRARY){const o=document.createElement('option');o.value=c.id;o.textContent=c.title+' · '+c.tag;$('caseselect').append(o);}
$('caseselect').onchange=e=>selectCase(e.target.value);
const originalRenderQuestions=renderQuestions;
renderQuestions=function(){originalRenderQuestions();if(testAnswers)testAnswers.forEach((a,i)=>$('answer'+i).value=a);};
selectCase('family');
$('loaddemo').onclick=()=>{if(recording||busy){message('Wait for recording or transcription to finish.');return;}selectCase('family');photos=TEST_KIT.visuals.map(v=>({name:v.name,url:v.url}));gallery();$('transcript').value=TEST_KIT.transcript;testAnswers=[...TEST_KIT.answers];revealed=false;feedback=null;sessionStarted=false;deadline=null;$('results').replaceChildren();$('download').disabled=true;$('demostatus').textContent='Synthetic test data loaded: 3 visuals, transcript and answers. Answers appear after you reveal questions.';show(1);message('Synthetic test kit loaded. Click Finish presentation & reveal questions, then Evaluate our roleplay.');};
